import { useId, useState } from 'react';
import styles from './Backgrounds.module.css';

/**
 * CSS backgrounds: gradients and a photo "hero" banner with overlay text.
 *
 * - Gradients are IMAGES generated by CSS: linear-, radial-, conic-gradient().
 * - Several backgrounds can be layered, separated by commas – the first one
 *   is on top. A semi-transparent gradient over a photo keeps text readable.
 * - Values that change with state go in the inline `style` object; the
 *   fixed styling lives in the CSS Module.
 */
const PRESETS = [
  { name: 'Sunset', css: 'linear-gradient(135deg, #f97316, #db2777)' },
  { name: 'Ocean', css: 'linear-gradient(to right, #0ea5e9, #6366f1)' },
  { name: 'Spotlight', css: 'radial-gradient(circle at 30% 30%, #fde68a, #f59e0b 40%, #7c2d12)' },
  { name: 'Colour wheel', css: 'conic-gradient(red, yellow, lime, aqua, blue, magenta, red)' },
  { name: 'Stripes', css: 'repeating-linear-gradient(45deg, #6366f1 0 10px, #818cf8 10px 20px)' },
];

export default function Backgrounds() {
  const id = useId();
  const [overlay, setOverlay] = useState(0.55);
  const [position, setPosition] = useState('center');
  const [type, setType] = useState('linear');
  const [angle, setAngle] = useState(120);
  const [from, setFrom] = useState('#4f46e5');
  const [to, setTo] = useState('#0e9f8e');

  const custom =
    type === 'linear' ? `linear-gradient(${angle}deg, ${from}, ${to})`
      : type === 'radial' ? `radial-gradient(circle, ${from}, ${to})`
        : `conic-gradient(from ${angle}deg, ${from}, ${to}, ${from})`;

  return (
    <div className="stack-lg">
      {/* Hero banner: two background layers – a dark gradient on top of a photo */}
      <section
        className={styles.hero}
        style={{
          backgroundImage: `linear-gradient(rgb(0 0 0 / ${overlay}), rgb(0 0 0 / ${overlay * 0.4})), url(https://picsum.photos/seed/cos30049-hero/1400/600)`,
          backgroundPosition: position,
        }}
      >
        <p className={styles.eyebrow}>COS30049 · Demo day</p>
        <h3 className={styles.heroTitle}>Show the world what your team built</h3>
        <p className={styles.heroText}>Friday 23 October · Hawthorn campus · All welcome</p>
      </section>
      <div className="row">
        <label className="row small" htmlFor={`${id}-overlay`} style={{ gap: 6 }}>
          Overlay darkness
          <input id={`${id}-overlay`} type="range" min="0" max="0.9" step="0.05" value={overlay}
            onChange={(e) => setOverlay(Number(e.target.value))} />
          <span className="mono">{overlay.toFixed(2)}</span>
        </label>
        <label className="row small" style={{ gap: 6 }}>
          background-position
          <select className="input" style={{ width: 110, height: 32 }} value={position} onChange={(e) => setPosition(e.target.value)}>
            <option>center</option>
            <option>top</option>
            <option>bottom</option>
          </select>
        </label>
      </div>

      <ul className={styles.presets}>
        {PRESETS.map((preset) => (
          <li key={preset.name} className="stack-sm">
            <div className={styles.swatch} style={{ background: preset.css }} />
            <strong className="small">{preset.name}</strong>
            <code className={styles.code}>{preset.css}</code>
          </li>
        ))}
      </ul>

      <div className="grid-2">
        <div className="stack-sm">
          <h4 className="m-0">Gradient builder</h4>
          <div className="btn-group" role="group" aria-label="Gradient type">
            {['linear', 'radial', 'conic'].map((t) => (
              <button key={t} type="button" className={`btn btn-sm ${type === t ? 'active' : ''}`}
                aria-pressed={type === t} onClick={() => setType(t)}>
                {t}
              </button>
            ))}
          </div>
          <label className="row small" style={{ gap: 6 }}>
            Angle <input type="range" min="0" max="360" value={angle} onChange={(e) => setAngle(Number(e.target.value))}
              disabled={type === 'radial'} /> {angle}°
          </label>
          <div className="row small">
            <label className="row" style={{ gap: 6 }}>
              From <input type="color" value={from} onChange={(e) => setFrom(e.target.value)} />
            </label>
            <label className="row" style={{ gap: 6 }}>
              To <input type="color" value={to} onChange={(e) => setTo(e.target.value)} />
            </label>
          </div>
          <pre className="demo-output m-0">{`background: ${custom};`}</pre>
        </div>
        <div className={styles.preview} style={{ background: custom }} role="img" aria-label="Preview of the custom gradient" />
      </div>
    </div>
  );
}
